fn now_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock")
        .as_millis() as i64
}

fn now_secs() -> i64 {
    now_ms() / 1_000
}

fn phc(password: &str) -> String {
    apex_control::passwords::hash_with_salt(password, b"apex-control-live").expect("hash")
}

fn operator(id: &str, name: &str, role: &str, secret: &str) -> OperatorConfig {
    OperatorConfig {
        id: id.to_string(),
        name: name.to_string(),
        role: role.to_string(),
        password_argon2id_phc: phc(PASSWORD),
        totp_secret_base32: Some(secret.to_string()),
    }
}

