fn sha(payload: &str) -> String {
    apex_control::signing::sha256_hex(payload.as_bytes())
}

fn seed_ledgers(root: &Path) -> Keypair {
    std::fs::create_dir_all(root).expect("ledger root");
    let key = Keypair::from_bytes(&[9u8; 32]);
    let at = now_ms();
    let mut ledger =
        Ledger::open(root.join("northstar.jsonl"), key.clone()).expect("open northstar");
    ledger
        .append(LedgerRecord::experiment_started(
            at - 3 * 86_400_000,
            PlatformId::AppLovinMax,
            "exp_e2e",
            ExperimentSpec {
                name: "E2E floor test".to_string(),
                ad_unit_id: "unit_e2e".to_string(),
                metric: ExperimentMetric::Ecpm,
                variants: 2,
                change_description: "raise the floor by 40 bp".to_string(),
                test_group_allocation: 25,
            },
        ))
        .expect("experiment started");
    ledger
        .append(LedgerRecord::experiment_observed(
            at - 2 * 86_400_000,
            PlatformId::AppLovinMax,
            "exp_e2e",
            ExperimentResult {
                experiment_id: "exp_e2e".to_string(),
                state: ExperimentState::Completed,
                results: vec![ExperimentVariantResult {
                    variant_id: "treatment".to_string(),
                    impressions: 100_000,
                    revenue: 155_000_000,
                    ecpm: 1_550_000,
                }],
                lift_percent_bp: Some(120),
                confidence: Some(9_800),
                winner_variant_id: Some("treatment".to_string()),
            },
        ))
        .expect("experiment observed");
    let lift_payload = r#"{"liftBp":120,"confidence":9800}"#;
    ledger
        .append(LedgerRecord::lift_record(
            at - 86_400_000,
            &sha(lift_payload),
            lift_payload,
        ))
        .expect("lift");
    ledger
        .append(LedgerRecord::billing_proof(
            at - 10 * 86_400_000,
            "northstar",
            "exp_e2e",
            10_000_000_000,
            2_000,
            2_000_000_000,
        ))
        .expect("billing proof");
    drop(ledger);
    let mut orbit = Ledger::open(root.join("orbit.jsonl"), key.clone()).expect("open orbit");
    orbit
        .append(LedgerRecord::lift_record(
            at - 2 * 86_400_000,
            &sha("{\"orbit\":1}"),
            "{\"orbit\":1}",
        ))
        .expect("orbit lift");
    drop(orbit);
    // An unverified publisher file (no configured key) must never be served.
    let other = Keypair::from_bytes(&[7u8; 32]);
    let mut unverified =
        Ledger::open(root.join("unverified.jsonl"), other).expect("open unverified");
    unverified
        .append(LedgerRecord::lift_record(at, &sha("{}"), "{}"))
        .expect("unverified lift");
    key
}

fn write_snapshot(root: &Path, publisher: &str, platform: &str, fetched_at_ms: i64, units: usize) {
    let dir = root.join(publisher);
    std::fs::create_dir_all(&dir).expect("snapshot dir");
    let units: Vec<serde_json::Value> = (0..units)
        .map(|index| serde_json::json!({"platformUnitId": format!("u{index}")}))
        .collect();
    std::fs::write(
        dir.join(format!("{platform}.json")),
        serde_json::to_vec(&serde_json::json!({
            "fetchedAtUnixMs": fetched_at_ms,
            "adUnits": units,
        }))
        .expect("json"),
    )
    .expect("snapshot");
}

fn month() -> String {
    apex_analytics::UtcMillis::from_unix_millis(now_ms()).to_month_string()
}

fn day(delta_days: i64) -> String {
    apex_analytics::UtcMillis::from_unix_millis(now_ms() - delta_days * 86_400_000).to_day_string()
}

