fn seed_job(dir: &Path) -> String {
    std::fs::create_dir_all(dir).expect("jobs dir");
    let mut job = OperatorJob::queued(
        JobKind::RetryRead,
        "maya",
        now_ms() - 3_600_000,
        "northstar:applovin_max:acct_max",
        serde_json::json!({"platform": "applovin_max", "account": "acct_max"}),
        &random_hex_32(),
        "corr-live-job",
    );
    job.state = "failed".to_string();
    job.outcome = Some("platform timeout".to_string());
    job.state_history.push(apex_control::jobs::JobStateEntry {
        state: "failed".to_string(),
        at_ms: now_ms() - 3_500_000,
        note: "the platform read timed out".to_string(),
    });
    let id = job.job_id.clone();
    std::fs::write(
        dir.join(format!("{id}.json")),
        serde_json::to_vec_pretty(&job).expect("job json"),
    )
    .expect("job file");
    id
}

fn seed_policies(path: &Path) -> String {
    let mut out = String::new();
    let mut first = String::new();
    for index in 0..10_000u32 {
        let record = apex_control::governance::PolicyRecord::draft(
            "ada",
            now_ms() - 86_400_000,
            serde_json::json!({"cap": index}),
            serde_json::json!({"window": 14}),
            serde_json::json!({"min": 100}),
            "future proposals",
            index + 1,
            &format!("corr-policy-{index}"),
        );
        if index == 0 {
            first = record.policy_id.clone();
        }
        out.push_str(&serde_json::to_string(&record).expect("json"));
        out.push('\n');
    }
    std::fs::write(path, out).expect("policies");
    first
}

fn seed_journal(path: &Path) {
    let mut entries = String::with_capacity(40 * 1024 * 1024);
    for index in 0..100_000usize {
        let entry = ActionJournalEntry {
            at_ms: index as i64,
            actor: "maya".to_string(),
            role: "operator".to_string(),
            capability: "retry_read".to_string(),
            capability_class: "ingestion".to_string(),
            target: format!("publisher{index}:applovin_max:acct"),
            outcome: "requested".to_string(),
            reason: "recorded".to_string(),
            before_digest: "a".repeat(64),
            after_digest: "b".repeat(64),
            idempotency_key: apex_control::signing::idempotency_fingerprint(&format!("k{index}")),
            payload_fingerprint: None,
            result_id: Some(format!("res_{index:012x}")),
            job_id: None,
            correlation_id: "c".to_string(),
        };
        entries.push_str(&serde_json::to_string(&entry).expect("json"));
        entries.push('\n');
    }
    std::fs::write(path, entries).expect("journal");
}

fn seed_workdir() -> (PathBuf, Keypair) {
    let work = std::env::temp_dir().join(format!(
        "apex-control-live-{}-{}",
        std::process::id(),
        random_hex_32()
    ));
    let _ = std::fs::remove_dir_all(&work);
    std::fs::create_dir_all(&work).expect("work");
    std::fs::create_dir_all(work.join("snapshots")).expect("snapshots");
    std::fs::create_dir_all(work.join("jobs")).expect("jobs");
    std::fs::create_dir_all(work.join("connections")).expect("connections");
    write_operators(&work.join("operators.json"));
    let key = seed_ledgers(&work.join("ledgers"));
    let at = now_ms();
    write_snapshot(
        &work.join("snapshots"),
        "northstar",
        "applovin_max",
        at - 7_200_000,
        3,
    );
    write_snapshot(
        &work.join("snapshots"),
        "northstar",
        "levelplay",
        at - 30 * 3_600_000,
        2,
    );
    write_snapshot(
        &work.join("snapshots"),
        "orbit",
        "applovin_max",
        at - 5 * 3_600_000,
        0,
    );
    seed_invoices(&work.join("invoices.jsonl"));
    seed_job(&work.join("jobs"));
    seed_policies(&work.join("policies.jsonl"));
    seed_journal(&work.join("journal.jsonl"));
    std::fs::write(
        work.join("sync-marker.json"),
        serde_json::to_vec(&serde_json::json!({
            "synced_at_unix_ms": at - 3_600_000,
            "source": "ledger",
        }))
        .expect("json"),
    )
    .expect("sync marker");
    std::fs::write(work.join("operations.json"), "[]".as_bytes()).expect("operations");
    (work, key)
}

fn free_port() -> u16 {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind");
    listener.local_addr().expect("addr").port()
}

fn wait_ready(port: u16) {
    let deadline = Instant::now() + Duration::from_secs(30);
    loop {
        if std::net::TcpStream::connect(("127.0.0.1", port)).is_ok() {
            return;
        }
        if Instant::now() > deadline {
            panic!("server on {port} did not become ready");
        }
        std::thread::sleep(Duration::from_millis(50));
    }
}

fn api_bin() -> Option<PathBuf> {
    std::env::var("APEX_API_BIN")
        .ok()
        .map(PathBuf::from)
        .filter(|path| path.exists())
}

fn control_bin() -> PathBuf {
    PathBuf::from(env!("CARGO_BIN_EXE_apex-control"))
}

#[allow(clippy::too_many_arguments)]
fn start_control(
    work: &Path,
    port: u16,
    remote: Option<(&str, &str)>,
    clickhouse: Option<(&str, &str)>,
    extra_env: &[(&str, &str)],
) -> Child {
    let mut command = Command::new(control_bin());
    command.env_clear();
    command
        .env("APEX_CONTROL_BIND", format!("127.0.0.1:{port}"))
        .env("APEX_ENVIRONMENT", "TEST")
        .env("APEX_CONTROL_OPERATORS", work.join("operators.json"))
        .env("APEX_CONTROL_JOURNAL", work.join("journal.jsonl"))
        .env("APEX_CONTROL_TOTP_STATE", work.join("totp-steps.json"))
        .env("APEX_CONTROL_LEDGER_ROOT", work.join("ledgers"))
        .env(
            "APEX_CONTROL_LEDGER_KEYS",
            format!("northstar={},orbit={}", hex_key(), hex_key()),
        )
        .env("APEX_RUNNER_SNAPSHOT", work.join("snapshots"))
        .env("APEX_CONTROL_INVOICE_REGISTER", work.join("invoices.jsonl"))
        .env("APEX_OPERATOR_JOBS_DIR", work.join("jobs"))
        .env("APEX_CONTROL_SYNC_MARKER", work.join("sync-marker.json"))
        .env("APEX_CONTROL_OPERATIONS", work.join("operations.json"))
        .env("APEX_CONTROL_POLICIES", work.join("policies.jsonl"))
        .env(
            "APEX_CONTROL_INTERVENTIONS",
            work.join("interventions.jsonl"),
        )
        .env("APEX_CONTROL_CONNECTIONS_ROOT", work.join("connections"))
        .env("APEX_EFFECTIVE_POLICY", work.join("effective-policy.json"))
        .env("APEX_CONTROL_SESSION_IDLE_SECONDS", "1800")
        .stdout(Stdio::null())
        .stderr(Stdio::from(
            std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(work.join("control-stderr.log"))
                .expect("control stderr"),
        ));
    if let Some((url, token)) = remote {
        command
            .env("APEX_API_JOBS_URL", url)
            .env("APEX_OPERATOR_JOBS_TOKEN", token);
    }
    if let Some((http, db)) = clickhouse {
        command
            .env("APEX_CLICKHOUSE_HTTP", http)
            .env("APEX_CLICKHOUSE_DB", db);
    }
    for (name, value) in extra_env {
        command.env(name, value);
    }
    command.spawn().expect("spawn apex-control")
}

fn hex_key() -> String {
    hex::encode(Keypair::from_bytes(&[9u8; 32]).verifying_key().to_bytes())
}

fn start_api(work: &Path, port: u16, token: &str) -> Child {
    let bin = api_bin().expect("APEX_API_BIN");
    let mut command = Command::new(bin);
    command.env_clear();
    command
        .env("APEX_API_BIND", format!("127.0.0.1:{port}"))
        .env("APEX_OPERATOR_JOBS_TOKEN", token)
        .env("APEX_OPERATOR_JOBS_DIR", work.join("api-jobs"))
        .env(
            "APEX_CONTROL_INTERVENTIONS",
            work.join("api-interventions.jsonl"),
        )
        .env(
            "APEX_EFFECTIVE_POLICY",
            work.join("api-effective-policy.json"),
        )
        .env("APEX_CREDENTIAL_ROOT", work.join("api-connections"))
        .env("APEX_VAULT_KEY_HEX", "22".repeat(32))
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    command.spawn().expect("spawn apex-api")
}

fn client_ip(index: usize) -> String {
    format!("198.51.100.{}", index % 250 + 1)
}

struct Response {
    status: StatusCode,
    headers: HeaderMap,
    body: String,
}

async fn get(http: &reqwest::Client, base: &str, path: &str, cookie: Option<&str>) -> Response {
    let mut request = http.get(format!("{base}{path}"));
    if let Some(cookie) = cookie {
        request = request.header(COOKIE, cookie);
    }
    let response = request.send().await.expect("GET");
    let status = response.status();
    let headers = response.headers().clone();
    let body = response.text().await.expect("body");
    Response {
        status,
        headers,
        body,
    }
}

async fn post(
    http: &reqwest::Client,
    base: &str,
    path: &str,
    cookie: Option<&str>,
    form: &[(String, String)],
    extra: &[(&str, &str)],
) -> Response {
    let mut request = http.post(format!("{base}{path}")).form(form);
    if let Some(cookie) = cookie {
        request = request.header(COOKIE, cookie);
    }
    for (name, value) in extra {
        request = request.header(*name, *value);
    }
    let response = request.send().await.expect("POST");
    let status = response.status();
    let headers = response.headers().clone();
    let body = response.text().await.expect("body");
    Response {
        status,
        headers,
        body,
    }
}

fn set_cookie(headers: &HeaderMap) -> Option<String> {
    headers
        .get(SET_COOKIE)
        .and_then(|value| value.to_str().ok())
        .map(str::to_string)
}

fn cookie_pair(set_cookie: &str) -> String {
    set_cookie.split(';').next().unwrap_or_default().to_string()
}

fn attr_unescape(value: &str) -> String {
    value
        .replace("&quot;", "\"")
        .replace("&#39;", "'")
        .replace("&amp;", "&")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
}

fn hidden_inputs(chunk: &str) -> HashMap<String, String> {
    let mut fields = HashMap::new();
    let mut rest = chunk;
    while let Some(start) = rest.find("<input") {
        rest = &rest[start..];
        let Some(end) = rest.find('>') else { break };
        let tag = &rest[..end];
        let name = attr(tag, "name");
        let value = attr(tag, "value").unwrap_or_default();
        if let Some(name) = name {
            fields.insert(name, attr_unescape(&value));
        }
        rest = &rest[end + 1..];
    }
    fields
}

fn attr(tag: &str, name: &str) -> Option<String> {
    let needle = format!("{name}=\"");
    let start = tag.find(&needle)? + needle.len();
    let end = tag[start..].find('"')? + start;
    Some(tag[start..end].to_string())
}

fn form_for(html: &str, kind: &str, target: &str) -> Option<HashMap<String, String>> {
    let action = format!("action=\"/control/actions/{kind}\"");
    let mut rest = html;
    while let Some(start) = rest.find("<form") {
        rest = &rest[start..];
        let end = rest.find("</form>").unwrap_or(rest.len());
        let chunk = &rest[..end];
        if chunk.contains(&action) {
            let fields = hidden_inputs(chunk);
            if fields.get("target").map(String::as_str) == Some(target) {
                return Some(fields);
            }
        }
        rest = &rest[end..];
    }
    None
}

fn any_form_for(html: &str, kind: &str) -> Option<HashMap<String, String>> {
    let action = format!("action=\"/control/actions/{kind}\"");
    let mut rest = html;
    while let Some(start) = rest.find("<form") {
        rest = &rest[start..];
        let end = rest.find("</form>").unwrap_or(rest.len());
        let chunk = &rest[..end];
        if chunk.contains(&action) {
            return Some(hidden_inputs(chunk));
        }
        rest = &rest[end..];
    }
    None
}

fn csrf_from(html: &str) -> Option<String> {
    hidden_inputs(html).get("csrf_token").cloned()
}

struct SignedIn {
    cookie: String,
    csrf: String,
    set_cookie: String,
}

async fn sign_in(
    http: &reqwest::Client,
    base: &str,
    operator: &str,
    secret_b32: &str,
    secure: bool,
    ip_index: usize,
) -> SignedIn {
    let ip = client_ip(ip_index);
    let login = post(
        http,
        base,
        "/control/login",
        None,
        &[
            ("operator".to_string(), operator.to_string()),
            ("password".to_string(), PASSWORD.to_string()),
        ],
        &[("X-Forwarded-For", &ip)],
    )
    .await;
    assert_eq!(
        login.status,
        StatusCode::OK,
        "password step: {}",
        login.body
    );
    let pending = hidden_inputs(&login.body)
        .get("pending")
        .cloned()
        .unwrap_or_else(|| panic!("no pending token in {}", login.body));
    let secret = base32::decode(secret_b32).expect("secret");
    if now_secs().rem_euclid(30) > 27 {
        tokio::time::sleep(Duration::from_secs(4)).await;
    }
    let code = totp::code_at(&secret, now_secs());
    let mut extra: Vec<(&str, &str)> = vec![("X-Forwarded-For", &ip)];
    if secure {
        extra.push(("X-Forwarded-Proto", "https"));
    }
    let step = post(
        http,
        base,
        "/control/login/code",
        None,
        &[("pending".to_string(), pending), ("code".to_string(), code)],
        &extra,
    )
    .await;
    assert_eq!(
        step.status,
        StatusCode::SEE_OTHER,
        "code step: {}",
        step.body
    );
    let set_cookie = set_cookie(&step.headers).expect("session cookie");
    let cookie = cookie_pair(&set_cookie);
    // The CSRF token is on every authenticated page.
    let page = get(http, base, "/control/", Some(&cookie)).await;
    assert_eq!(page.status, StatusCode::OK, "{}", page.body);
    let csrf = csrf_from(&page.body).expect("csrf");
    SignedIn {
        cookie,
        csrf,
        set_cookie,
    }
}

async fn submit_action(
    http: &reqwest::Client,
    base: &str,
    cookie: &str,
    kind: &str,
    form: &HashMap<String, String>,
) -> Response {
    // The rendered form carries the hidden CSRF/version/identity fields plus
    // empty visible inputs (reason, confirmation, ...). Override those last
    // empty values instead of sending both an empty and a filled field.
    let mut fields: BTreeMap<String, String> = form
        .iter()
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();
    let blank = |fields: &BTreeMap<String, String>, name: &str| {
        fields.get(name).is_none_or(|value| value.trim().is_empty())
    };
    if blank(&fields, "reason") {
        fields.insert("reason".to_string(), "live verification reason".to_string());
    }
    fields.insert(
        "evidence".to_string(),
        "confirming read from the platform".to_string(),
    );
    fields.insert("source_document".to_string(), "LIVE-E2E-SOURCE".to_string());
    let confirmation = confirmation_for(kind);
    if !confirmation.is_empty() {
        fields.insert("confirmation".to_string(), confirmation.to_string());
    }
    if blank(&fields, "policy_json") {
        fields.insert(
            "policy_json".to_string(),
            serde_json::to_string(&apex_autopilot::model::AutopilotPolicy::conservative())
                .expect("policy"),
        );
    }
    if blank(&fields, "revenue_30d_micros") {
        fields.insert("revenue_30d_micros".to_string(), "2000000000".to_string());
    }
    if blank(&fields, "tier") {
        fields.insert("tier".to_string(), "base".to_string());
    }
    if blank(&fields, "customer_population") {
        fields.insert(
            "customer_population".to_string(),
            "all publishers".to_string(),
        );
    }
    if blank(&fields, "expected_effect") {
        fields.insert(
            "expected_effect".to_string(),
            "no new scheduling until resume".to_string(),
        );
    }
    let fields: Vec<(String, String)> = fields.into_iter().collect();
    post(
        http,
        base,
        &format!("/control/actions/{kind}"),
        Some(cookie),
        &fields,
        &[],
    )
    .await
}

fn confirmation_for(kind: &str) -> &'static str {
    match kind {
        "fleet_pause_scheduling" => "PAUSE SCHEDULING",
        "fleet_resume_scheduling" => "RESUME SCHEDULING",
        "policy_activate" => "ACTIVATE POLICY",
        "policy_set" => "SET POLICY",
        "managed_plan_activate" => "ACTIVATE MANAGED PLAN",
        "session_revoke" => "REVOKE SESSION",
        _ => "",
    }
}

async fn finish_action(
    http: &reqwest::Client,
    base: &str,
    cookie: &str,
    kind: &str,
    response: &Response,
    result_ids: &mut Vec<(String, String)>,
) -> String {
    assert_eq!(
        response.status,
        StatusCode::SEE_OTHER,
        "{kind}: {}",
        response.body
    );
    let location = response
        .headers
        .get(reqwest::header::LOCATION)
        .and_then(|value| value.to_str().ok())
        .unwrap_or_else(|| panic!("{kind}: no Location"));
    let page = get(http, base, location, Some(cookie)).await;
    assert_eq!(page.status, StatusCode::OK, "{kind} result: {}", page.body);
    assert!(
        !page.body.contains("The action failed"),
        "{kind} result page reported failure: {}",
        page.body
    );
    let result_id = location.rsplit('/').next().unwrap_or_default().to_string();
    result_ids.push((kind.to_string(), result_id.clone()));
    result_id
}

