// ClickHouse seed (real server; generated data, real schema and projections)
// ---------------------------------------------------------------------------

fn ch_time(ms: i64) -> String {
    apex_analytics::UtcMillis::from_unix_millis(ms).to_clickhouse()
}

#[allow(clippy::too_many_arguments)]
fn ch_event(
    id: &str,
    event_type: &str,
    occurred_ms: i64,
    publisher: &str,
    platform: Option<&str>,
    object_type: &str,
    object_id: &str,
    outcome: Option<&str>,
    payload: serde_json::Value,
) -> serde_json::Value {
    serde_json::json!({
        "event_id": id,
        "event_type": event_type,
        "schema_version": 1,
        "occurred_at_utc": ch_time(occurred_ms),
        "received_at_utc": ch_time(occurred_ms + 1),
        "environment": "dev",
        "service_version": "apex-control-live-seed",
        "source": "worker",
        "publisher_id": publisher,
        "platform": platform,
        "object_type": object_type,
        "object_id": object_id,
        "outcome": outcome,
        "payload_json": payload.to_string(),
    })
}

async fn ch_insert(
    http: &reqwest::Client,
    base: &str,
    db: &str,
    table: &str,
    rows: &[serde_json::Value],
) {
    if rows.is_empty() {
        return;
    }
    let body = rows
        .iter()
        .map(|row| row.to_string())
        .collect::<Vec<_>>()
        .join("\n");
    let response = http
        .post(format!("{}/?database={db}", base.trim_end_matches('/')))
        .header("Content-Type", "text/plain")
        .body(format!(
            "INSERT INTO {db}.{table} FORMAT JSONEachRow\n{body}\n"
        ))
        .send()
        .await
        .expect("clickhouse insert");
    let status = response.status();
    let text = response.text().await.unwrap_or_default();
    assert!(status.is_success(), "clickhouse {table}: {status} {text}");
}

